query:
fragment issue on Issue {number}query IssueSearch($repo: String!, $owner: String!, $type: SearchType!, $limit: Int, $after: String, $query: String!) {
      repository(name: $repo, owner: $owner) {
        hasIssuesEnabled
      }
      search(type: $type, last: $limit, after: $after, query: $query) {
        issueCount
        nodes { ...issue }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
